import{_ as r,C as o,o as a,c as n,a2 as s,E as d}from"./chunks/framework.CGSzHL4z.js";const y=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"reference/performance.md","filePath":"reference/performance.md","lastUpdated":1793203250000}'),i={name:"reference/performance.md"};function c(l,e,h,m,p,f){const t=o("Screenshot");return a(),n("div",null,[e[0]||(e[0]=s('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>How AcesMotion keeps Studio responsive and the runtime cheap in your game.</p><h2 id="in-your-game" tabindex="-1">In your game <a class="header-anchor" href="#in-your-game" aria-label="Permalink to &quot;In your game&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>How it stays cheap</th></tr></thead><tbody><tr><td>Network</td><td>The server sends one message per play, not one per frame. Clients evaluate scenes themselves from the server clock, so traffic doesn&#39;t grow with scene length or frame rate.</td></tr><tr><td>Clock</td><td>Play time follows the server clock (<code>workspace:GetServerTimeNow()</code>), never the frame delta, so a hitch on one machine doesn&#39;t leave it behind. A client more than 0.05 s off re-anchors instead of drifting.</td></tr><tr><td>Joints</td><td>Written once a frame in <code>PreSimulation</code>, after the Animator has posed the rig, so a scene blends over idle and walk without stopping it.</td></tr><tr><td>Scene data</td><td>Stored in a compact binary form inside the place.</td></tr><tr><td>Distance</td><td><code>Configure { MaxDistance = ... }</code> lets clients skip scenes too far away to see.</td></tr><tr><td>Sounds</td><td>At most 16 copies of one sound play at once. The oldest stops first.</td></tr><tr><td>Streaming</td><td>Cast members are bound when they stream in, so StreamingEnabled games don&#39;t need every actor loaded.</td></tr><tr><td>Dependencies</td><td>None from outside: the runtime is the engine plus two small packages (Signal and Trove).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Avoid a first-play hitch</p><p><code>Preload</code> decodes scenes ahead of time, so the first play doesn&#39;t hitch.</p></div><h2 id="in-studio" tabindex="-1">In Studio <a class="header-anchor" href="#in-studio" aria-label="Permalink to &quot;In Studio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>How it stays quick</th></tr></thead><tbody><tr><td>Shared engine</td><td>The plugin and the runtime share the engine byte for byte, so there is one well-tested code path.</td></tr><tr><td>Time</td><td>Stored as integer ticks, 6000 per second. Every common frame rate lands exactly on ticks, so changing the frame rate never shifts keys or accumulates rounding.</td></tr><tr><td>Storage</td><td>A scene is stored per chunk (one per actor). An edit rewrites only the chunks it touched, inside one undo step, so big scenes stay quick to edit and Team Create stays light.</td></tr><tr><td>Dope sheet</td><td>Virtualised: only the rows and keys on screen exist, and their instances are reused as you scroll.</td></tr><tr><td>Waveforms</td><td>Read in 2 second chunks as they scroll into view. Every zoom level is built from those chunks locally.</td></tr><tr><td>Previews</td><td>Motion trails sample at most 600 points, and the particle preview has a cap you control (Settings &gt; Effects).</td></tr><tr><td>Crash recovery</td><td>The recovery copy is written 2 seconds after an edit instead of on every change, so it doesn&#39;t stall editing.</td></tr></tbody></table>',7)),d(t,{name:"performance-big-scene",caption:"A large scene scrolling smoothly in the dope sheet."})])}const g=r(i,[["render",c]]);export{y as __pageData,g as default};
